bounded_host_request.command:
set -euo pipefail
root="$HOME/Project/Gserver/projects/TGtumbler/GateApp-Bot"
test "$(git -C "$root" remote get-url origin | sed -E 's#^git@github.com:#https://github.com/#')" = "https://github.com/seigo-gace/GateApp-Bot.git" || { echo ORIGIN_MISMATCH; exit 41; }
src=cfc999ac40962b936c6dbe83648d0d2fab421fdd
stage="$root/.worktrees/bug-report-20261115"
mkdir -p "$root/.worktrees"
if [ -e "$stage" ]; then
 test "$(git -C "$stage" rev-parse HEAD)" = "$src" || { echo STAGE_HEAD_CONFLICT; exit 42; }
else
 git -C "$root" fetch --no-tags origin "$src" >/dev/null 2>&1 || { echo FETCH_FAILED; exit 43; }
 test "$(git -C "$root" rev-parse FETCH_HEAD)" = "$src" || { echo FETCH_SHA_MISMATCH; exit 44; }
 git -C "$root" worktree add --detach "$stage" "$src" >/dev/null 2>&1 || { echo STAGE_FAILED; exit 45; }
fi
test "$(git -C "$stage" rev-parse --show-toplevel)" = "$stage" || exit 46
test -z "$(git -C "$stage" status --porcelain)" || exit 47
test -f "$stage/artifacts/bot/src/bot/bugReportHandlers.ts" || exit 48
image=gace-tgtumbler-gaybbs:bugreport-cfc999ac
docker build --network host --pull=false -f "$stage/artifacts/bot/deploy/Dockerfile.gaybbs" -t "$image" "$stage" >/tmp/gace-bugreport-build.log 2>&1 || { echo BUILD_FAILED; grep -Ei 'error|failed' /tmp/gace-bugreport-build.log | tail -n 3 | sed -E 's#https?://[^ ]+#URL_REDACTED#g' || true; exit 49; }
docker run --rm --network none --pull never --entrypoint node "$image" --check /app/gaybbs.mjs >/dev/null 2>&1 || { echo IMAGE_CHECK_FAILED; exit 50; }
echo BUGREPORT_IMAGE_STAGE=PASS
echo SOURCE_SHA="$src"
echo CREATED_NEW_TOP_LEVEL_SIBLING=NO
